// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(address recipient, uint256 reward) public {
        vm.assume(recipient != address(0));
        reward = bound(reward, 1, 1 ether);

        Reverter rev = new Reverter();

        Receiver recv = new Receiver();

        address target = (uint160(recipient) & 1 == 1) ? address(rev) : address(recv);

        vm.deal(address(c), reward + 1);

        reward = 100;

        vm.deal(address(c), reward);

        bool ok;
        try c.getFirstWithdrawalBonus(target) {
            ok = true;
        } catch {
            ok = false;
        }

        bool withdrawOk;
        try c.withdrawReward(target) {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        assertTrue(!ok || withdrawOk);
    }
}

contract Reverter { fallback() external payable { revert(); } }
contract Receiver { receive() external payable { } }
